Example player character blueprint code:
```scss
UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Inventory")
TArray<UItemBase\*> Inventory;

void AddItem(UItemBase\* Item)
{
    if (Item)
    {
        Inventory.Add(Item);
    }
}

void RemoveItem(UItemBase\* Item)
{
    if (Item)
    {
        Inventory.Remove(Item);
    }
}

void UseItem(UItemBase\* Item)
{
    if (Item && Item->ItemEffectClass)
    {
        UItemEffect* ItemEffect = GetWorld()->SpawnActor<UItemEffect>(Item->ItemEffectClass);
        if (ItemEffect)
        {
            ItemEffect->ApplyEffect(this);
        }
    }
}
```
